//! Acceptance tests of spec node SCAN.EDGE.EST.EFIX (AC-1 .. AC-3, REQ-001 .. REQ-003).
//!
//! The case table, grid sizes and per-station truths come from the independent Python
//! reference `fixtures/scan/edge/make_efix_truths.py` (closed-form truths in 60-digit decimal
//! arithmetic, rounded once to the nearest double), written to
//! `fixtures/scan/edge/efix_truths.txt`; nothing there was generated by running this crate.
//! Truth coordinates are compared within `TRUTH_TOL_M` (rounding of the crate's double
//! arithmetic), sizes exactly. AC-1 is also checked hand-labelled from the spec's numbers.
//!
//! REQ-001 and AC-3 measure the generated points against this file's own description of the
//! analytic profile (`Profile2`), written from the spec rules independently of the crate's
//! sampler. AC-2 and REQ-003: the manifests under `fixtures/scan/edge/est_*/manifest.json` pin
//! the `GEO.TYPES` content digests of every variant's cloud and mesh. They are regression pins
//! written by this generator (run with `FID_EFIX_WRITE=1` to rewrite them after a deliberate
//! change); CI checks them on Linux x86-64, Windows x86-64, macOS ARM64 and wasm32-wasip1, so
//! equal pins on every target are the cross-target byte identity. Their truths are checked
//! against the Python reference here as well.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use core::f64::consts::{FRAC_PI_2, FRAC_PI_6};

use fid_geo_types::digest::{digest_mesh, digest_point_cloud};
use fid_scan_edge::testkit::{
    edge_fixture, fixture_manifest, named_fixture, named_fixtures, validate, Coverage, EdgeFixture, EdgeFixtureSpec,
    EdgeProfile, EfixError, NominalPath, StationFrame, MANIFEST_FORMAT, MAX_POINTS, NOISY_SIGMA_M,
};

const TRUTHS: &str = include_str!("../../../fixtures/scan/edge/efix_truths.txt");

/// Tolerance on truth coordinates and station frames: the crate evaluates the closed forms in
/// double arithmetic (a few roundings of millimetre-sized values, about 1e-19 m each).
const TRUTH_TOL_M: f64 = 1e-15;

const MANIFESTS: [(&str, &str); 8] = [
    ("est_sharp_onesided", include_str!("../../../fixtures/scan/edge/est_sharp_onesided/manifest.json")),
    ("est_sharp_wrapped", include_str!("../../../fixtures/scan/edge/est_sharp_wrapped/manifest.json")),
    ("est_round1_onesided", include_str!("../../../fixtures/scan/edge/est_round1_onesided/manifest.json")),
    ("est_round1_wrapped", include_str!("../../../fixtures/scan/edge/est_round1_wrapped/manifest.json")),
    ("est_chamfer05_onesided", include_str!("../../../fixtures/scan/edge/est_chamfer05_onesided/manifest.json")),
    ("est_chamfer05_wrapped", include_str!("../../../fixtures/scan/edge/est_chamfer05_wrapped/manifest.json")),
    ("est_burr02_onesided", include_str!("../../../fixtures/scan/edge/est_burr02_onesided/manifest.json")),
    ("est_burr02_wrapped", include_str!("../../../fixtures/scan/edge/est_burr02_wrapped/manifest.json")),
];

// ---------------------------------------------------------------------------------------------
// The reference file.

fn hx(s: &str) -> f64 {
    assert_eq!(s.len(), 16, "hex float {s}");
    f64::from_bits(u64::from_str_radix(s, 16).unwrap())
}

fn hx_vec<const N: usize>(s: &str) -> [f64; N] {
    let v: Vec<f64> = s.split(',').map(hx).collect();
    v.try_into().unwrap()
}

#[derive(Debug, Clone)]
struct RefStation {
    frame: StationFrame,
    trim: f64,
    tang: Option<[f64; 2]>,
    silh: [f64; 2],
}

#[derive(Debug, Clone)]
struct RefCase {
    name: String,
    spec: EdgeFixtureSpec,
    seed: u64,
    noisy_sigma: f64,
    grid: [u64; 4],
    stations: Vec<RefStation>,
}

fn kv(tokens: &[&str]) -> Vec<(String, String)> {
    tokens
        .iter()
        .map(|t| {
            let (k, v) = t.split_once('=').unwrap_or_else(|| panic!("token {t}"));
            (k.to_string(), v.to_string())
        })
        .collect()
}

fn get<'a>(m: &'a [(String, String)], k: &str) -> &'a str {
    &m.iter().find(|(kk, _)| kk == k).unwrap_or_else(|| panic!("missing {k}")).1
}

fn parse_profile(s: &str) -> EdgeProfile {
    let parts: Vec<&str> = s.split(':').collect();
    match parts[0] {
        "sharp" => EdgeProfile::Sharp,
        "round" => EdgeProfile::Round { radius_m: hx(parts[1]) },
        "chamfer" => EdgeProfile::Chamfer { width_m: hx(parts[1]) },
        "burr" => EdgeProfile::Burr { height_m: hx(parts[1]), width_m: hx(parts[2]) },
        other => panic!("profile {other}"),
    }
}

fn parse_path(s: &str) -> NominalPath {
    let parts: Vec<&str> = s.split(':').collect();
    match parts[0] {
        "straight" => NominalPath::Straight { length_m: hx(parts[1]) },
        "arc" => NominalPath::Arc { radius_m: hx(parts[1]), length_m: hx(parts[2]) },
        other => panic!("path {other}"),
    }
}

fn reference() -> Vec<RefCase> {
    let mut lines = TRUTHS.lines();
    assert!(lines.next().unwrap().starts_with('#'));
    assert_eq!(lines.next(), Some("efix-truths 1"));
    assert!(!TRUTHS.contains('\r'), "LF line endings");
    let mut cases: Vec<RefCase> = Vec::new();
    for line in lines {
        let tok: Vec<&str> = line.split(' ').collect();
        match tok[0] {
            "case" => {
                let m = kv(&tok[2..]);
                let coverage = match get(&m, "coverage") {
                    "onesided" => Coverage::OneSided,
                    "wrapped" => Coverage::Wrapped,
                    other => panic!("coverage {other}"),
                };
                cases.push(RefCase {
                    name: tok[1].to_string(),
                    spec: EdgeFixtureSpec {
                        profile: parse_profile(get(&m, "profile")),
                        thickness_m: hx(get(&m, "thickness")),
                        trim_offset_m: hx(get(&m, "trim")),
                        coverage,
                        nominal_edge: parse_path(get(&m, "path")),
                        spacing_m: hx(get(&m, "spacing")),
                        sigma_m: hx(get(&m, "sigma")),
                        top_extent_m: hx(get(&m, "top")),
                        bottom_extent_m: hx(get(&m, "bottom")),
                        station_count: get(&m, "stations").parse().unwrap(),
                        threshold_rad: hx(get(&m, "theta")),
                    },
                    seed: get(&m, "seed").parse().unwrap(),
                    noisy_sigma: hx(get(&m, "noisy_sigma")),
                    grid: [0; 4],
                    stations: Vec::new(),
                });
            }
            "grid" => {
                let c = cases.last_mut().unwrap();
                assert_eq!(tok[1], c.name);
                let m = kv(&tok[2..]);
                c.grid = ["rows", "cols", "points", "triangles"].map(|k| get(&m, k).parse().unwrap());
            }
            "station" => {
                let c = cases.last_mut().unwrap();
                assert_eq!(tok[1], c.name);
                assert_eq!(tok[2].parse::<usize>().unwrap(), c.stations.len());
                let m = kv(&tok[3..]);
                c.stations.push(RefStation {
                    frame: StationFrame {
                        p: hx_vec(get(&m, "p")),
                        t: hx_vec(get(&m, "t")),
                        n: hx_vec(get(&m, "n")),
                        b: hx_vec(get(&m, "b")),
                    },
                    trim: hx(get(&m, "trim")),
                    tang: match get(&m, "tang") {
                        "none" => None,
                        s => Some(hx_vec(s)),
                    },
                    silh: hx_vec(get(&m, "silh")),
                });
            }
            other => panic!("record {other}"),
        }
    }
    assert_eq!(cases.len(), 14, "8 named and 6 extra cases");
    cases
}

fn close(a: f64, b: f64, tol: f64, what: &str) {
    assert!((a - b).abs() <= tol, "{what}: {a:e} vs {b:e} (diff {:e})", (a - b).abs());
}

fn close_n(a: &[f64], b: &[f64], tol: f64, what: &str) {
    assert_eq!(a.len(), b.len());
    for (x, y) in a.iter().zip(b) {
        close(*x, *y, tol, what);
    }
}

// ---------------------------------------------------------------------------------------------
// This file's own analytic profile (from the spec rules), for REQ-001 and AC-3.

enum Piece {
    /// From `a` to `b`, outward unit normal `nrm`.
    Line { a: [f64; 2], b: [f64; 2], nrm: [f64; 2] },
    /// `c + r (sin phi, cos phi)` for `phi` in `[0, pi/2]`.
    Quarter { c: [f64; 2], r: f64 },
}

struct Profile2 {
    pieces: Vec<Piece>,
}

fn line(a: [f64; 2], b: [f64; 2], nrm: [f64; 2]) -> Piece {
    Piece::Line { a, b, nrm }
}

impl Profile2 {
    fn new(s: &EdgeFixtureSpec) -> Profile2 {
        let (t, e) = (s.thickness_m, s.trim_offset_m);
        let top0 = [e - s.top_extent_m, 0.0];
        let bot = |u0: f64| line([u0, -t], [e - s.bottom_extent_m, -t], [0.0, -1.0]);
        let up = [0.0, 1.0];
        let out = [1.0, 0.0];
        let pieces = match s.profile {
            EdgeProfile::Sharp => vec![line(top0, [e, 0.0], up), line([e, 0.0], [e, -t], out), bot(e)],
            EdgeProfile::Round { radius_m: r } => vec![
                line(top0, [e - r, 0.0], up),
                Piece::Quarter { c: [e - r, -r], r },
                line([e, -r], [e, -t], out),
                bot(e),
            ],
            EdgeProfile::Chamfer { width_m: c } => {
                let h = core::f64::consts::FRAC_1_SQRT_2;
                vec![
                    line(top0, [e - c, 0.0], up),
                    line([e - c, 0.0], [e, -c], [h, h]),
                    line([e, -c], [e, -t], out),
                    bot(e),
                ]
            }
            EdgeProfile::Burr { height_m: h, width_m: w } => vec![
                line(top0, [e, 0.0], up),
                line([e, 0.0], [e, -(t - h)], out),
                line([e, -(t - h)], [e + w, -(t - h)], up),
                line([e + w, -(t - h)], [e + w, -t], out),
                bot(e + w),
            ],
        };
        Profile2 { pieces }
    }

    /// Signed distance of `q` to the profile (positive outside the material) and the piece's
    /// normal at the foot point.
    fn distance(&self, q: [f64; 2]) -> (f64, [f64; 2]) {
        let mut best = (f64::INFINITY, 0.0, [0.0, 0.0]);
        for p in &self.pieces {
            let (d, s, nrm) = match *p {
                Piece::Line { a, b, nrm } => {
                    let (du, dv) = (b[0] - a[0], b[1] - a[1]);
                    let l2 = du * du + dv * dv;
                    if l2 == 0.0 {
                        continue;
                    }
                    let tau = (((q[0] - a[0]) * du + (q[1] - a[1]) * dv) / l2).clamp(0.0, 1.0);
                    let f = [a[0] + du * tau, a[1] + dv * tau];
                    let (x, y) = (q[0] - f[0], q[1] - f[1]);
                    let d = (x * x + y * y).sqrt();
                    let s = x * nrm[0] + y * nrm[1];
                    (d, if s < 0.0 { -1.0 } else { 1.0 }, nrm)
                }
                Piece::Quarter { c, r } => {
                    let (x, y) = (q[0] - c[0], q[1] - c[1]);
                    let phi = x.atan2(y);
                    if (0.0..=FRAC_PI_2).contains(&phi) {
                        let rho = (x * x + y * y).sqrt();
                        let nrm = [phi.sin(), phi.cos()];
                        ((rho - r).abs(), if rho < r { -1.0 } else { 1.0 }, nrm)
                    } else {
                        continue; // the end points belong to the neighbouring lines
                    }
                }
            };
            if d < best.0 {
                best = (d, s, nrm);
            }
        }
        (best.0 * best.1, best.2)
    }
}

/// Station coordinates `(u, v)` and path position of a part-frame point.
fn to_station(edge: NominalPath, q: [f64; 3]) -> ([f64; 2], f64) {
    match edge {
        NominalPath::Straight { .. } => ([q[0], q[2]], q[1]),
        NominalPath::Arc { radius_m, .. } => {
            let rho = (q[0] * q[0] + q[1] * q[1]).sqrt();
            ([rho - radius_m, q[2]], q[1].atan2(q[0]) * radius_m)
        }
    }
}

fn points(f: &EdgeFixture) -> Vec<[f64; 3]> {
    (0..f.cloud().len()).map(|i| f.cloud().point(i).unwrap()).collect()
}

// ---------------------------------------------------------------------------------------------
// Reference agreement: case table, sizes, truths.

#[test]
fn named_set_matches_the_reference_table() {
    let refs = reference();
    let named = named_fixtures();
    assert_eq!(named.len(), 8);
    for (i, nf) in named.iter().enumerate() {
        let r = &refs[i];
        assert_eq!(nf.name, r.name);
        assert_eq!(nf.spec, r.spec, "{}", nf.name);
        assert_eq!(nf.seed, r.seed, "{}", nf.name);
        assert_eq!(nf.seed, 61 + i as u64);
        assert_eq!(NOISY_SIGMA_M, r.noisy_sigma);
    }
    // The 30-degree threshold of the set is the double nearest pi/6 (the reference checks its
    // literal against 60-digit pi).
    assert_eq!(named[0].spec.threshold_rad, FRAC_PI_6);
}

#[test]
fn grid_sizes_and_truths_match_the_reference() {
    for r in reference() {
        let f = edge_fixture(&r.spec, r.seed).unwrap_or_else(|e| panic!("{}: {e}", r.name));
        let (rows, cols) = f.grid();
        assert_eq!([rows, cols, f.cloud().len(), f.mesh().triangle_count()], r.grid, "{} grid", r.name);
        assert_eq!(f.mesh().vertex_count(), f.cloud().len());
        assert_eq!(f.cloud().attributes().grid, Some((rows, cols)));
        assert_eq!(f.truths().len(), r.stations.len(), "{} stations", r.name);
        for (st, rs) in f.truths().iter().zip(&r.stations) {
            let what = format!("{} station {}", r.name, st.index());
            let fr = st.frame();
            close_n(&fr.p, &rs.frame.p, TRUTH_TOL_M, &format!("{what} p"));
            close_n(&fr.t, &rs.frame.t, 1e-15, &format!("{what} t"));
            close_n(&fr.n, &rs.frame.n, 1e-15, &format!("{what} n"));
            close_n(&fr.b, &rs.frame.b, 1e-15, &format!("{what} b"));
            assert_eq!(st.trim_offset_m(), rs.trim, "{what} trim");
            match (st.tangency_uv(), rs.tang) {
                (Some(a), Some(b)) => close_n(&a, &b, TRUTH_TOL_M, &format!("{what} tangency")),
                (None, None) => {}
                (a, b) => panic!("{what} tangency {a:?} vs {b:?}"),
            }
            close_n(&st.silhouette_uv(), &rs.silh, TRUTH_TOL_M, &format!("{what} silhouette"));
        }
    }
}

// ---------------------------------------------------------------------------------------------
// AC-1 (hand-labelled from the spec's numbers).

#[test]
fn ac1_round_silhouette_and_tangency_truth() {
    let f = named_fixture("est_round1_wrapped", 0.0).unwrap();
    let s = f.spec();
    assert_eq!(s.profile, EdgeProfile::Round { radius_m: 1.0e-3 });
    assert_eq!((s.thickness_m, s.trim_offset_m, s.sigma_m), (1.0e-3, 0.5e-3, 0.0));
    assert_eq!(s.threshold_rad, FRAC_PI_6);
    for st in f.truths() {
        let fr = st.frame();
        // Silhouette: the nominal edge plus 0.5 mm along b.
        let sil = fr.world(st.silhouette_uv());
        let expected = [fr.p[0] + 0.5e-3 * fr.b[0], fr.p[1] + 0.5e-3 * fr.b[1], fr.p[2] + 0.5e-3 * fr.b[2]];
        close(sil[0], expected[0], 1e-18, "silhouette x");
        close(sil[1], expected[1], 1e-18, "silhouette y");
        assert_eq!(st.silhouette_uv()[0], 0.5e-3);
        // Tangency for 30 degrees: r sin(30 deg) = 0.5 mm past the start of the round, which
        // is at u = e - r = -0.5 mm.
        let tang = st.tangency_uv().unwrap();
        close(tang[0] - (0.5e-3 - 1.0e-3), 0.5e-3, 1e-18, "tangency past round start");
        // ... at depth r (1 - cos 30 deg).
        close(tang[1], -(1.0e-3 - 1.0e-3 * 0.866_025_403_784_438_6), 1e-18, "tangency depth");
    }
}

// ---------------------------------------------------------------------------------------------
// REQ-001: noise-free points on the analytic profile.

#[test]
fn req1_clean_points_lie_on_the_profile() {
    for r in reference() {
        let f = edge_fixture(&r.spec, r.seed).unwrap();
        let prof = Profile2::new(&r.spec);
        let normals = f.cloud().attributes();
        let mut worst = 0.0f64;
        let mut creased = 0u64;
        for (i, q) in points(&f).into_iter().enumerate() {
            let (uv, s) = to_station(r.spec.nominal_edge, q);
            assert!(
                (-1e-15..=r.spec.nominal_edge.length_m() + 1e-15).contains(&s),
                "{} point {i} off the path",
                r.name
            );
            let (d, nrm) = prof.distance(uv);
            worst = worst.max(d.abs());
            // Interior samples carry the analytic normal at their foot point; junction samples
            // a unit bisector. Every normal is unit length and faces out of the material.
            let n = normals.normal_at(i as u64).unwrap();
            let len = (n[0] * n[0] + n[1] * n[1] + n[2] * n[2]).sqrt();
            close(len, 1.0, 1e-15, "normal length");
            let fr = r.spec.nominal_edge.frame_at(s).unwrap();
            let nuv =
                [n[0] * fr.b[0] + n[1] * fr.b[1] + n[2] * fr.b[2], n[0] * fr.n[0] + n[1] * fr.n[1] + n[2] * fr.n[2]];
            let dot = nuv[0] * nrm[0] + nuv[1] * nrm[1];
            // A crease sample's bisector is within half the fold (at most 135 degrees, the full
            // chamfer's bottom corner) of either side; every other sample matches exactly.
            assert!(dot > 0.38, "{} point {i}: normal {nuv:?} vs profile {nrm:?}", r.name);
            if dot < 1.0 - 1e-12 {
                creased += 1;
            }
        }
        assert!(worst <= 1e-12, "{}: worst distance to the profile {worst:e} m", r.name);
        // At most four crease columns (the burr's) per row.
        assert!(creased <= 4 * f.grid().0, "{}: {creased} samples off the analytic normal", r.name);
    }
}

#[test]
fn one_sided_coverage_is_what_is_visible_from_above() {
    let sharp = named_fixture("est_sharp_onesided", 0.0).unwrap();
    assert!(points(&sharp).iter().all(|q| q[2] == 0.0), "sharp: top face only");
    // Burr: the top face and the ledge, which stands out past the edge face and faces +n;
    // nothing of the edge face, the burr face or the bottom face.
    let burr = named_fixture("est_burr02_onesided", 0.0).unwrap();
    let (e, w, ledge) = (0.5e-3, 0.2e-3, -(1.0e-3 - 0.2e-3));
    let pts = points(&burr);
    assert!(pts.iter().all(|q| q[2] == 0.0 || q[2] == ledge), "burr: top face and ledge only");
    let on_ledge: Vec<_> = pts.iter().filter(|q| q[2] == ledge).collect();
    assert!(on_ledge.iter().all(|q| (e..=e + w).contains(&q[0])), "burr ledge within [e, e + w]");
    assert!(on_ledge.iter().any(|q| q[0] == e + w), "burr: the ledge's outer end is sampled");
    assert_eq!(on_ledge.len() as u64, 5 * burr.grid().0, "burr: five ledge columns per row");
    assert_eq!(burr.mesh().facts().components, 2, "burr: top face and ledge are separate pieces");
    for name in ["est_round1_onesided", "est_chamfer05_onesided"] {
        let f = named_fixture(name, 0.0).unwrap();
        let e = f.spec().trim_offset_m;
        // Nothing beyond the trim line, nothing on the bottom face except the end of the
        // round or chamfer, and the round or chamfer is there.
        let pts = points(&f);
        assert!(pts.iter().all(|q| q[0] <= e), "{name}");
        assert!(pts.iter().any(|q| q[2] < -0.25e-3), "{name}: the round or chamfer is sampled");
    }
    let wrapped = named_fixture("est_sharp_wrapped", 0.0).unwrap();
    assert!(points(&wrapped).iter().any(|q| q[2] == -1.0e-3 && q[0] < 0.0), "wrapped reaches the bottom face");
}

#[test]
fn mesh_is_the_cloud_oriented_and_facing_out_of_the_material() {
    for r in reference() {
        let f = edge_fixture(&r.spec, r.seed).unwrap();
        // The mesh has exactly the cloud's points as its vertices, in the same order.
        assert_eq!(f.mesh().vertex_count(), f.cloud().len(), "{}", r.name);
        for i in 0..f.cloud().len() {
            assert_eq!(f.mesh().vertex(i), f.cloud().point(i), "{} vertex {i}", r.name);
        }
        let facts = f.mesh().facts();
        // One piece, except one-sided burr coverage (top face and ledge).
        let pieces = match (r.spec.profile, r.spec.coverage) {
            (EdgeProfile::Burr { .. }, Coverage::OneSided) => 2,
            _ => 1,
        };
        assert_eq!(facts.components, pieces, "{}", r.name);
        assert!(facts.oriented, "{}", r.name);
        assert_eq!(facts.nonmanifold_edges, 0, "{}", r.name);
        assert_eq!(facts.degenerate, 0, "{}", r.name);
        let normals = f.cloud().attributes();
        for t in f.mesh().triangles() {
            let [a, b, c] = t.map(|i| f.mesh().vertex(i).unwrap());
            let (u, v) = ([b[0] - a[0], b[1] - a[1], b[2] - a[2]], [c[0] - a[0], c[1] - a[1], c[2] - a[2]]);
            let x = [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]];
            let n = normals.normal_at(t[0]).unwrap();
            assert!(x[0] * n[0] + x[1] * n[1] + x[2] * n[2] > 0.0, "{} triangle {t:?} faces inward", r.name);
        }
    }
}

// ---------------------------------------------------------------------------------------------
// AC-3: sigma = 10 micrometres gives a residual standard deviation of 10 micrometres +- 5 %.

#[test]
fn ac3_noise_standard_deviation() {
    for nf in named_fixtures() {
        let f = named_fixture(nf.name, NOISY_SIGMA_M).unwrap();
        let prof = Profile2::new(&nf.spec);
        let res: Vec<f64> =
            points(&f).into_iter().map(|q| prof.distance(to_station(nf.spec.nominal_edge, q).0).0).collect();
        let n = res.len() as f64;
        let mean = res.iter().sum::<f64>() / n;
        let var = res.iter().map(|r| (r - mean) * (r - mean)).sum::<f64>() / (n - 1.0);
        let sd = var.sqrt();
        eprintln!("{}: residual sd {sd:e} m, mean {mean:e} m over {n} points", nf.name);
        assert!((9.5e-6..=10.5e-6).contains(&sd), "{}: residual sd {sd:e} m over {n} points", nf.name);
        assert!(mean.abs() < 1.5e-6, "{}: residual mean {mean:e} m", nf.name);
    }
}

// ---------------------------------------------------------------------------------------------
// AC-2 and REQ-003: byte identity per seed, pinned across targets.

#[test]
fn ac2_same_seed_same_digests_and_manifests_pin_them() {
    let write = std::env::var_os("FID_EFIX_WRITE").is_some();
    let named = named_fixtures();
    for (nf, (name, committed)) in named.iter().zip(MANIFESTS) {
        assert_eq!(nf.name, name);
        let a = fixture_manifest(nf).unwrap();
        let b = fixture_manifest(nf).unwrap();
        assert_eq!(a, b, "{name}: two runs differ");
        if write {
            let dir = format!("{}/../../fixtures/scan/edge/{name}", env!("CARGO_MANIFEST_DIR"));
            std::fs::create_dir_all(&dir).unwrap();
            std::fs::write(format!("{dir}/manifest.json"), &a).unwrap();
            continue;
        }
        assert_eq!(a, committed, "{name}: manifest differs from the committed pin on {}", std::env::consts::ARCH);
    }
}

#[test]
fn manifests_are_synthetic_and_carry_the_reference_truths() {
    let refs = reference();
    for ((name, text), r) in MANIFESTS.iter().zip(&refs) {
        assert_eq!(*name, r.name);
        assert!(text.starts_with(&format!("{{\"format\":\"{MANIFEST_FORMAT}\",\n")));
        assert!(text.contains("\n\"data\":\"synthetic\",\n"), "{name}: D-045 synthetic marker");
        assert!(text.contains(&format!("\n\"seed\":{},\n", r.seed)));
        assert!(!text.contains('\r'));
        for (k, rs) in r.stations.iter().enumerate() {
            let line = text.lines().find(|l| l.contains(&format!("{{\"index\":{k},"))).unwrap();
            let h = |x: f64| format!("\"{:016x}\"", if x == 0.0 { 0.0f64 } else { x }.to_bits());
            // The committed truths agree with the reference within TRUTH_TOL_M: parse them back.
            let field = |key: &str| -> Vec<f64> {
                let i = line.find(&format!("\"{key}\":[")).unwrap() + key.len() + 4;
                let j = line[i..].find(']').unwrap() + i;
                line[i..j].split(',').map(|s| hx(s.trim_matches('"'))).collect()
            };
            close_n(&field("silhouette_uv"), &rs.silh, TRUTH_TOL_M, &format!("{name} manifest silhouette"));
            close_n(&field("tangency_uv"), &rs.tang.unwrap(), TRUTH_TOL_M, &format!("{name} manifest tangency"));
            close_n(&field("p"), &rs.frame.p, TRUTH_TOL_M, &format!("{name} manifest p"));
            assert!(line.contains(&format!("\"trim_offset_m\":{}", h(rs.trim))));
        }
    }
}

#[test]
fn seed_changes_only_the_noisy_variant() {
    let spec = named_fixtures()[3].spec;
    let a = edge_fixture(&spec, 1).unwrap();
    let b = edge_fixture(&spec, 2).unwrap();
    assert_eq!(digest_point_cloud(a.cloud()), digest_point_cloud(b.cloud()), "clean ignores the seed");
    let noisy = EdgeFixtureSpec { sigma_m: NOISY_SIGMA_M, ..spec };
    let (c, d, e) =
        (edge_fixture(&noisy, 1).unwrap(), edge_fixture(&noisy, 2).unwrap(), edge_fixture(&noisy, 1).unwrap());
    assert_ne!(digest_point_cloud(c.cloud()), digest_point_cloud(d.cloud()));
    assert_eq!(digest_point_cloud(c.cloud()), digest_point_cloud(e.cloud()));
    assert_eq!(digest_mesh(c.mesh()), digest_mesh(e.mesh()));
    assert_eq!(c, e);
    // The noise moves points along their (unchanged) normals only.
    assert_eq!(c.cloud().attributes().normal, a.cloud().attributes().normal);
}

// ---------------------------------------------------------------------------------------------
// Error paths: every refused spec names the field and the rule; nothing is generated.

fn base() -> EdgeFixtureSpec {
    named_fixtures()[3].spec
}

fn refused(spec: EdgeFixtureSpec) -> EfixError {
    let e = edge_fixture(&spec, 0).expect_err("refused");
    assert_eq!(
        validate(&spec).err().as_ref().map(|x| x.code()),
        Some(e.code()).filter(|c| *c != "efix.too_many_points")
    );
    e
}

fn field_of(e: &EfixError) -> &'static str {
    match e {
        EfixError::NonFinite { field } | EfixError::OutOfRange { field, .. } => field,
        other => panic!("unexpected {other:?}"),
    }
}

#[test]
fn refused_specs_name_field_and_rule() {
    let b = base();
    let cases: Vec<(EdgeFixtureSpec, &str, &str)> = vec![
        (EdgeFixtureSpec { thickness_m: f64::NAN, ..b }, "efix.non_finite", "thickness_m"),
        (EdgeFixtureSpec { thickness_m: 0.0, ..b }, "efix.out_of_range", "thickness_m"),
        (EdgeFixtureSpec { thickness_m: 2.0, ..b }, "efix.out_of_range", "thickness_m"),
        (EdgeFixtureSpec { trim_offset_m: f64::INFINITY, ..b }, "efix.non_finite", "trim_offset_m"),
        (EdgeFixtureSpec { trim_offset_m: -1.5, ..b }, "efix.out_of_range", "trim_offset_m"),
        (
            EdgeFixtureSpec { profile: EdgeProfile::Round { radius_m: 1.5e-3 }, ..b },
            "efix.out_of_range",
            "profile.radius_m",
        ),
        (
            EdgeFixtureSpec { profile: EdgeProfile::Round { radius_m: -1e-3 }, ..b },
            "efix.out_of_range",
            "profile.radius_m",
        ),
        (
            EdgeFixtureSpec { profile: EdgeProfile::Chamfer { width_m: 1.01e-3 }, ..b },
            "efix.out_of_range",
            "profile.width_m",
        ),
        (
            EdgeFixtureSpec { profile: EdgeProfile::Burr { height_m: 1.0e-3, width_m: 1e-4 }, ..b },
            "efix.out_of_range",
            "profile.height_m",
        ),
        (
            EdgeFixtureSpec { profile: EdgeProfile::Burr { height_m: 1e-4, width_m: 0.0 }, ..b },
            "efix.out_of_range",
            "profile.width_m",
        ),
        (
            EdgeFixtureSpec { profile: EdgeProfile::Burr { height_m: f64::NAN, width_m: 1e-4 }, ..b },
            "efix.non_finite",
            "profile.height_m",
        ),
        (EdgeFixtureSpec { top_extent_m: 1.0e-3, ..b }, "efix.out_of_range", "top_extent_m"),
        (EdgeFixtureSpec { bottom_extent_m: 0.0, ..b }, "efix.out_of_range", "bottom_extent_m"),
        (
            EdgeFixtureSpec { nominal_edge: NominalPath::Straight { length_m: -1.0 }, ..b },
            "efix.out_of_range",
            "nominal_edge.length_m",
        ),
        (
            EdgeFixtureSpec { nominal_edge: NominalPath::Arc { radius_m: 1e-3, length_m: 3.2e-3 }, ..b },
            "efix.out_of_range",
            "nominal_edge.length_m",
        ),
        (
            EdgeFixtureSpec { nominal_edge: NominalPath::Arc { radius_m: 1e-3, length_m: 1e-3 }, ..b },
            "efix.out_of_range",
            "nominal_edge.radius_m",
        ),
        (EdgeFixtureSpec { spacing_m: 0.0, ..b }, "efix.out_of_range", "spacing_m"),
        (EdgeFixtureSpec { spacing_m: f64::NAN, ..b }, "efix.non_finite", "spacing_m"),
        (EdgeFixtureSpec { sigma_m: -1e-6, ..b }, "efix.out_of_range", "sigma_m"),
        (EdgeFixtureSpec { sigma_m: f64::NAN, ..b }, "efix.non_finite", "sigma_m"),
        (EdgeFixtureSpec { station_count: 0, ..b }, "efix.out_of_range", "station_count"),
        (EdgeFixtureSpec { station_count: 10_001, ..b }, "efix.out_of_range", "station_count"),
        (EdgeFixtureSpec { threshold_rad: 0.0, ..b }, "efix.out_of_range", "threshold_rad"),
        (EdgeFixtureSpec { threshold_rad: core::f64::consts::PI, ..b }, "efix.out_of_range", "threshold_rad"),
        (EdgeFixtureSpec { threshold_rad: f64::NAN, ..b }, "efix.non_finite", "threshold_rad"),
    ];
    for (spec, code, field) in cases {
        let e = refused(spec);
        assert_eq!((e.code(), field_of(&e)), (code, field), "{spec:?}");
        assert!(e.to_string().starts_with(code), "{e}");
    }
}

#[test]
fn oversized_grids_are_refused_before_allocation() {
    for spacing in [1e-9, 1e-300, f64::MIN_POSITIVE] {
        let spec = EdgeFixtureSpec { spacing_m: spacing, ..base() };
        assert!(validate(&spec).is_ok());
        match edge_fixture(&spec, 0) {
            Err(EfixError::TooManyPoints { needed, limit }) => {
                assert_eq!(limit, MAX_POINTS);
                assert!(needed > MAX_POINTS, "{needed}");
            }
            other => panic!("spacing {spacing:e}: {other:?}"),
        }
    }
    assert!(named_fixture("est_magic", 0.0).is_err());
}
